import{_ as e,o,c as a,ag as i}from"./chunks/framework.7He2WLS4.js";const u=JSON.parse('{"title":"Traffic Inspection","description":"Real-time HTTP/HTTPS traffic monitoring and inspection with NectoProxy.","frontmatter":{"title":"Traffic Inspection","description":"Real-time HTTP/HTTPS traffic monitoring and inspection with NectoProxy."},"headers":[],"relativePath":"features/traffic-inspection.md","filePath":"features/traffic-inspection.md","lastUpdated":1772297611000}'),r={name:"features/traffic-inspection.md"};function s(n,t,d,c,l,h){return o(),a("div",null,[...t[0]||(t[0]=[i(`<h1 id="traffic-inspection" tabindex="-1">Traffic Inspection <a class="header-anchor" href="#traffic-inspection" aria-label="Permalink to &quot;Traffic Inspection&quot;">​</a></h1><p>Traffic inspection is the core capability of NectoProxy. Every HTTP and HTTPS request that flows through the proxy is captured, decoded, and displayed in the Web UI in real time, giving you complete visibility into your application&#39;s network activity.</p><h2 id="how-mitm-interception-works" tabindex="-1">How MITM Interception Works <a class="header-anchor" href="#how-mitm-interception-works" aria-label="Permalink to &quot;How MITM Interception Works&quot;">​</a></h2><p>NectoProxy acts as a <strong>Man-in-the-Middle (MITM)</strong> proxy. When a client makes an HTTPS request through NectoProxy, the following process occurs:</p><ol><li><strong>Client connects</strong> to NectoProxy and issues a <code>CONNECT</code> request for the target host.</li><li><strong>NectoProxy establishes</strong> a TLS connection to the target server and retrieves its certificate details.</li><li><strong>NectoProxy generates</strong> a certificate for the target domain on the fly, signed by its own root Certificate Authority (CA).</li><li><strong>Client accepts</strong> the generated certificate (because NectoProxy&#39;s root CA has been installed as a trusted authority on the client system).</li><li><strong>Two separate TLS sessions</strong> are maintained -- one between the client and NectoProxy, and one between NectoProxy and the target server.</li><li><strong>NectoProxy decrypts, inspects, and re-encrypts</strong> all traffic flowing between the two endpoints.</li></ol><div class="warning custom-block"><p class="custom-block-title">Important</p><p>For HTTPS inspection to work, you must install and trust NectoProxy&#39;s root CA certificate on the client device. See the <a href="/nectoproxy/certificate/">Certificate Setup</a> guide for detailed instructions.</p></div><div class="tip custom-block"><p class="custom-block-title">SSL Passthrough</p><p>If you do not want NectoProxy to decrypt traffic for certain domains (e.g., banking sites or domains with certificate pinning), you can configure <a href="./ssl-passthrough.html">SSL Passthrough</a> to let that traffic flow through untouched.</p></div><h2 id="the-traffic-list" tabindex="-1">The Traffic List <a class="header-anchor" href="#the-traffic-list" aria-label="Permalink to &quot;The Traffic List&quot;">​</a></h2><p>The main view in NectoProxy is the traffic list, which displays all captured requests in a scrollable table. Each row shows key information at a glance:</p><table tabindex="0"><thead><tr><th>Column</th><th>Description</th></tr></thead><tbody><tr><td><strong>#</strong></td><td>Sequential request number</td></tr><tr><td><strong>Method</strong></td><td>HTTP method (GET, POST, PUT, DELETE, PATCH, etc.)</td></tr><tr><td><strong>Status</strong></td><td>HTTP response status code with color coding</td></tr><tr><td><strong>Host</strong></td><td>Target hostname</td></tr><tr><td><strong>Path</strong></td><td>Request URL path and query string</td></tr><tr><td><strong>Content Type</strong></td><td>Response content type (e.g., <code>application/json</code>)</td></tr><tr><td><strong>Size</strong></td><td>Response body size</td></tr><tr><td><strong>Duration</strong></td><td>Total round-trip time</td></tr><tr><td><strong>Protocol</strong></td><td>HTTP version and whether TLS was used</td></tr></tbody></table><h3 id="virtualized-rendering" tabindex="-1">Virtualized Rendering <a class="header-anchor" href="#virtualized-rendering" aria-label="Permalink to &quot;Virtualized Rendering&quot;">​</a></h3><p>The traffic list uses <strong>virtualized scrolling</strong> to handle thousands of captured entries without degrading UI performance. Only the rows currently visible in the viewport are rendered in the DOM. This means you can capture tens of thousands of requests in a single session without the UI slowing down.</p><details class="details custom-block"><summary>How Virtualization Works</summary><p>Rather than rendering every captured request as a DOM element, NectoProxy calculates which rows are visible based on the scroll position and viewport height. Only those rows are mounted in the DOM, with placeholder elements above and below to maintain correct scroll behavior. As you scroll, rows are recycled and re-populated with new data. This approach keeps memory usage and rendering cost constant regardless of how many entries have been captured.</p></details><h2 id="request-response-details-panel" tabindex="-1">Request &amp; Response Details Panel <a class="header-anchor" href="#request-response-details-panel" aria-label="Permalink to &quot;Request &amp; Response Details Panel&quot;">​</a></h2><p>Clicking on any entry in the traffic list opens the details panel, which provides a comprehensive view of the selected request and response.</p><h3 id="headers-tab" tabindex="-1">Headers Tab <a class="header-anchor" href="#headers-tab" aria-label="Permalink to &quot;Headers Tab&quot;">​</a></h3><p>Displays all request and response headers in a structured, readable format.</p><p><strong>Request headers</strong> include:</p><ul><li>Method, URL, and HTTP version</li><li>Host, User-Agent, Accept, Content-Type</li><li>Authorization, Cookie, and all custom headers</li></ul><p><strong>Response headers</strong> include:</p><ul><li>Status code and reason phrase</li><li>Content-Type, Content-Length, Content-Encoding</li><li>Set-Cookie, Cache-Control, and all other response headers</li></ul><h3 id="body-tab" tabindex="-1">Body Tab <a class="header-anchor" href="#body-tab" aria-label="Permalink to &quot;Body Tab&quot;">​</a></h3><p>The body tab renders request and response bodies with <strong>automatic syntax highlighting</strong> based on the content type:</p><table tabindex="0"><thead><tr><th>Content Type</th><th>Highlighting</th></tr></thead><tbody><tr><td><code>application/json</code></td><td>JSON with collapsible tree view</td></tr><tr><td><code>application/xml</code>, <code>text/xml</code></td><td>XML syntax highlighting</td></tr><tr><td><code>text/html</code></td><td>HTML syntax highlighting</td></tr><tr><td><code>application/javascript</code>, <code>text/javascript</code></td><td>JavaScript syntax highlighting</td></tr><tr><td><code>text/css</code></td><td>CSS syntax highlighting</td></tr><tr><td>Plain text</td><td>No highlighting, monospaced font</td></tr><tr><td>Binary data</td><td>Hex dump view</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Body Size Truncation</p><p>For performance reasons, very large response bodies are truncated in the UI display. The full body is still captured and available for export. A notice is displayed when truncation occurs, along with the actual body size.</p></div><h3 id="automatic-decompression" tabindex="-1">Automatic Decompression <a class="header-anchor" href="#automatic-decompression" aria-label="Permalink to &quot;Automatic Decompression&quot;">​</a></h3><p>NectoProxy automatically decompresses response bodies that use standard compression encodings:</p><ul><li><strong>gzip</strong> -- The most common HTTP compression format</li><li><strong>deflate</strong> -- The raw deflate compression algorithm</li><li><strong>Brotli</strong> (<code>br</code>) -- Google&#39;s modern compression format, increasingly used by CDNs</li></ul><p>The decompressed content is what you see in the body tab. The original <code>Content-Encoding</code> header is preserved in the headers tab so you can verify what compression was used.</p><h3 id="timing-tab" tabindex="-1">Timing Tab <a class="header-anchor" href="#timing-tab" aria-label="Permalink to &quot;Timing Tab&quot;">​</a></h3><p>The timing tab breaks down the lifecycle of each request into individual phases:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DNS Lookup    |----|</span></span>
<span class="line"><span>TCP Connect         |------|</span></span>
<span class="line"><span>TLS Handshake              |--------|</span></span>
<span class="line"><span>Request Send                        |--|</span></span>
<span class="line"><span>Waiting (TTFB)                         |------------|</span></span>
<span class="line"><span>Content Download                                     |------|</span></span></code></pre></div><p>Each phase shows its duration in milliseconds, giving you precise insight into where time is being spent. This is invaluable for diagnosing slow requests -- whether the bottleneck is DNS resolution, TLS negotiation, server processing time, or download speed.</p><h3 id="tls-tab" tabindex="-1">TLS Tab <a class="header-anchor" href="#tls-tab" aria-label="Permalink to &quot;TLS Tab&quot;">​</a></h3><p>For HTTPS requests, the TLS tab displays certificate and connection details:</p><ul><li><strong>Protocol version</strong> (TLS 1.2, TLS 1.3)</li><li><strong>Cipher suite</strong> used for the connection</li><li><strong>Server certificate</strong> details (subject, issuer, validity dates, serial number)</li><li><strong>Certificate chain</strong> information</li></ul><h2 id="filtering-traffic" tabindex="-1">Filtering Traffic <a class="header-anchor" href="#filtering-traffic" aria-label="Permalink to &quot;Filtering Traffic&quot;">​</a></h2><p>NectoProxy provides several ways to filter the traffic list so you can focus on the requests that matter.</p><h3 id="filter-bar" tabindex="-1">Filter Bar <a class="header-anchor" href="#filter-bar" aria-label="Permalink to &quot;Filter Bar&quot;">​</a></h3><p>The filter bar at the top of the traffic list supports filtering by multiple criteria simultaneously:</p><table tabindex="0"><thead><tr><th>Filter</th><th>Example</th><th>Description</th></tr></thead><tbody><tr><td><strong>Method</strong></td><td><code>GET</code>, <code>POST</code></td><td>Show only requests with the specified HTTP method</td></tr><tr><td><strong>Status</strong></td><td><code>200</code>, <code>4xx</code>, <code>5xx</code></td><td>Filter by exact status code or status class</td></tr><tr><td><strong>URL</strong></td><td><code>/api/users</code></td><td>Match requests whose URL contains the specified string</td></tr><tr><td><strong>Host</strong></td><td><code>api.example.com</code></td><td>Show only requests to a specific host</td></tr><tr><td><strong>Content Type</strong></td><td><code>application/json</code></td><td>Filter by response content type</td></tr></tbody></table><p>Filters can be combined. For example, you can filter for <code>POST</code> requests to <code>api.example.com</code> that returned a <code>500</code> status code.</p><h3 id="quick-filters" tabindex="-1">Quick Filters <a class="header-anchor" href="#quick-filters" aria-label="Permalink to &quot;Quick Filters&quot;">​</a></h3><p>Click on any value in the traffic list (such as a hostname, status code, or method) to instantly apply it as a filter. This is the fastest way to narrow down traffic when investigating a specific issue.</p><h3 id="example-debugging-api-errors" tabindex="-1">Example: Debugging API Errors <a class="header-anchor" href="#example-debugging-api-errors" aria-label="Permalink to &quot;Example: Debugging API Errors&quot;">​</a></h3><p>Suppose your application is experiencing intermittent 500 errors from your API:</p><ol><li>Set the <strong>Host</strong> filter to <code>api.example.com</code></li><li>Set the <strong>Status</strong> filter to <code>5xx</code></li><li>The traffic list now shows only failed API requests</li><li>Click on an entry to inspect the response body for error details</li><li>Check the timing tab to see if the errors correlate with slow response times</li></ol><h2 id="websocket-traffic" tabindex="-1">WebSocket Traffic <a class="header-anchor" href="#websocket-traffic" aria-label="Permalink to &quot;WebSocket Traffic&quot;">​</a></h2><p>NectoProxy also captures WebSocket upgrade requests. When a WebSocket connection is established, it appears in the traffic list with a special <code>WS</code> or <code>WSS</code> indicator. See <a href="./websocket-support.html">WebSocket Support</a> for complete details on WebSocket frame inspection.</p><h2 id="performance-considerations" tabindex="-1">Performance Considerations <a class="header-anchor" href="#performance-considerations" aria-label="Permalink to &quot;Performance Considerations&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Best Practices for High-Volume Traffic</p><ul><li>Use filters to narrow the display when capturing large amounts of traffic</li><li>Clear completed sessions when you no longer need the data</li><li>Enable <a href="./ssl-passthrough.html">SSL Passthrough</a> for domains you do not need to inspect to reduce processing overhead</li><li>The virtualized list handles thousands of entries efficiently, but keeping captured data to relevant traffic improves your debugging workflow</li></ul></div>`,51)])])}const g=e(r,[["render",s]]);export{u as __pageData,g as default};
